import{B,C,read,diagramStage,circle,path,pulse}from'../ten-utils.js';
export default({g,p,extra,t})=>{let m=extra.mode??0,k=p[0];
if(m===0){let names=[B('Mouth','मुख'),B('Oesophagus','ग्रासनली'),B('Stomach','आमाशय'),B('Small intestine','छोटी आँत'),B('Large intestine','बड़ी आँत')],pts=[[-.7,-.8,0],[-.5,-.35,0],[.15,0,0],[.1,.6,0],[.85,.65,0]];diagramStage(g,pts,k,t,names);return[read('Current organ','वर्तमान अंग',names[k]),read('Main role','मुख्य कार्य',[B('Chewing; salivary amylase acts on starch','चबाना; लार का एमाइलेज स्टार्च पर कार्य करता है'),B('Peristaltic movement','क्रमाकुंचन से भोजन आगे बढ़ता है'),B('Acid and pepsin; protein digestion begins','अम्ल और पेप्सिन; प्रोटीन का पाचन आरंभ'),B('Digestion completes; absorption through villi','पाचन पूर्ण; दीर्घरोम द्वारा अवशोषण'),B('Water absorption; undigested matter','जल का अवशोषण; अपचित पदार्थ')][k])]}
if(m===1){let co=extra.co2??1;g.sphere(0,0,0,.65,C.green,B('Leaf / chloroplast model','पत्ती / हरितलवक मॉडल'));for(let i=0;i<k/10;i++)g.arrow([-1.3,-.8+i*.15,0],[-.6,-.4+i*.1,0],C.gold);g.text(0,.95,0,B('CO2 + H2O → carbohydrate + O2','CO2 + H2O → कार्बोहाइड्रेट + O2'));return[read('Light input','प्रकाश निवेश',k,'%'),read('Carbon dioxide','कार्बन डाइऑक्साइड',co?B('Available','उपलब्ध'):B('Absent in model','मॉडल में अनुपस्थित')),read('Model response','मॉडल प्रतिक्रिया',co&&k>0?B('Photosynthesis possible; rate also depends on other factors','प्रकाश संश्लेषण संभव; दर अन्य कारकों पर भी निर्भर'):B('Photosynthesis cannot proceed without required input','आवश्यक निवेश के बिना प्रकाश संश्लेषण नहीं'))]}
if(m===2){let names=[B('Vena cava','महाशिरा'),B('Right atrium','दायाँ अलिंद'),B('Right ventricle','दायाँ निलय'),B('Lungs','फेफड़े'),B('Left atrium','बायाँ अलिंद'),B('Left ventricle','बायाँ निलय'),B('Body tissues','शरीर के ऊतक'),B('Venous return','शिराओं द्वारा वापसी')],pts=[[-1,.7,0],[-.6,0,0],[-.6,.5,0],[0,-.8,0],[.6,0,0],[.6,.5,0],[1.2,.8,0],[-1,1,0]];diagramStage(g,pts,k,t,names);return[read('Blood pathway','रक्त का मार्ग',names[k]),read('Oxygen content here','यहाँ ऑक्सीजन की मात्रा',k>=3&&k<=6?B('Relatively oxygen-rich after lungs; supplied to tissues','फेफड़ों के बाद अपेक्षाकृत अधिक; ऊतकों को आपूर्ति'):B('Relatively oxygen-poor on return to lungs','फेफड़ों की ओर लौटते रक्त में अपेक्षाकृत कम'))]}
if(m===3){circle(g,0,0,.7);for(let i=0;i<12;i++)g.sphere(Math.cos(i)*.45,Math.sin(i)*.45,0,.07,i<k*.12?C.blue:C.gold);g.text(0,-1,0,B('Glucose → energy-releasing pathways','ग्लूकोज़ → ऊर्जा मुक्त करने वाले मार्ग'));return[read('Oxygen supply','ऑक्सीजन आपूर्ति',k,'relative units'),read('Pathway','मार्ग',k===0?B('Anaerobic pathways can release less energy per glucose','अवायवीय मार्ग प्रति ग्लूकोज़ कम ऊर्जा मुक्त कर सकते हैं'):B('Oxygen permits aerobic breakdown; amount is not an ATP count','ऑक्सीजन से वायवीय विघटन संभव; यह ATP की संख्या नहीं'))]}
let pts=[[-1,-.5,0],[-.35,-.5,0],[.35,.4,0],[1,.7,0]],names=[B('Filtration','निस्यंदन'),B('Selective reabsorption','चयनात्मक पुनरवशोषण'),B('Tubular secretion','नलिकीय स्रवण'),B('Urine collection','मूत्र संग्रह')];diagramStage(g,pts,k,t,names);circle(g,-1,-.5,.25,C.pink);g.arrow([-.3,-.3,0],[-.3,.6,0],C.blue);return[read('Nephron stage','वृक्काणु की अवस्था',names[k]),read('Key distinction','मुख्य अंतर',B('Useful substances and much water return to blood; urine is not all filtrate','उपयोगी पदार्थ और बहुत-सा जल रक्त में लौटते हैं; पूरा निस्यंद मूत्र नहीं बनता'))]};
